def amicable_numbers_sum(n):
    def sum_of_divisors(num):
        if num <= 1:
            return 0
        total = 1
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                total += i
                if i != num // i:
                    total += num // i
        return total

    total_sum = 0
    for a in range(2, n + 1):
        b = sum_of_divisors(a)
        if b > a and b <= n and sum_of_divisors(b) == a:
            total_sum += a + b
    return total_sum
```

