def sum(a, b):
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    g = gcd(a, b)
    total = 0
    for i in range(1, int(g**0.5) + 1):
        if g % i == 0:
            total += i
            if i != g // i:
                total += g // i
    return total
```

