def find_solution(a, b, n):
    # Extended Euclidean Algorithm to find gcd and coefficients
    def extended_gcd(a, b):
        if b == 0:
            return a, 1, 0
        g, x1, y1 = extended_gcd(b, a % b)
        x = y1
        y = x1 - (a // b) * y1
        return g, x, y

    g, x0, y0 = extended_gcd(a, b)

    if n % g != 0:
        return None

    # Scale the solution
    x0 *= n // g
    y0 *= n // g

    # Find a solution with x >= 0 and y >= 0 if possible
    # General solution: x = x0 + (b/g)*t, y = y0 - (a/g)*t
    # We need x >= 0 and y >= 0
    # x >= 0 => t >= -x0 * g / b
    # y >= 0 => t <= y0 * g / a

    if b == 0:
        if a == 0:
            return (0, 0) if n == 0 else None
        if n % a == 0:
            return (n // a, 0)
        return None

    if a == 0:
        if n % b == 0:
            return (0, n // b)
        return None

    # Find t range
    t_min = -(-x0 * g // b) if b > 0 else -(-x0 * g // b)  # ceil(-x0*g/b)
    t_max = (y0 * g) // a if a > 0 else (y0 * g) // a  # floor(y0*g/a)

    # Adjust for negative denominators
    if b < 0:
        t_min = (x0 * g) // (-b)  # floor(x0*g/(-b))
    else:
        t_min = -(-x0 * g // b)  # ceil(-x0*g/b)

    if a < 0:
        t_max = -(-y0 * g // (-a))  # ceil(y0*g/a) when a negative
    else:
        t_max = (y0 * g) // a  # floor(y0*g/a)

    # Find any integer t in [t_min, t_max]
    if t_min > t_max:
        return None

    t = t_min
    x = x0 + (b // g) * t
    y = y0 - (a // g) * t

    return (x, y)
```

