def max_sub_array_sum_repeated(arr, n, k):
    def kadane(a):
        max_ending_here = max_so_far = a[0]
        for x in a[1:]:
            max_ending_here = max(x, max_ending_here + x)
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    total_sum = sum(arr)
    if k == 1:
        return kadane(arr)

    # For k > 1, consider two copies of the array
    double_arr = arr * 2
    max_subarray_two = kadane(double_arr)

    if total_sum > 0:
        return max_subarray_two + (k - 2) * total_sum
    else:
        return max_subarray_two
```

