def max_sum_increasing_subseq(arr, n, i, k):
    # dp[j] = max sum of increasing subsequence ending at index j
    dp = [0] * n
    for j in range(n):
        dp[j] = arr[j]
        for m in range(j):
            if arr[m] < arr[j]:
                dp[j] = max(dp[j], dp[m] + arr[j])

    # We need subsequence from prefix [0..i] and include element at k
    # So we find max dp[j] for j <= i where arr[j] < arr[k], then add arr[k]
    max_sum = 0
    for j in range(i + 1):
        if arr[j] < arr[k]:
            max_sum = max(max_sum, dp[j])

    return max_sum + arr[k]
```

