def set_left_most_unset_bit(n):
    # Find the position of the leftmost unset bit
    # Start from the most significant bit position
    bit_length = n.bit_length()

    # Check bits from left to right
    for i in range(bit_length - 1, -1, -1):
        if not (n & (1 << i)):
            # Set this bit
            return n | (1 << i)

    # If all bits are set, return n unchanged
    return n
