def find_kth(arr1, arr2, k):
    def kth(a, b, k):
        if not a:
            return b[k-1]
        if not b:
            return a[k-1]
        if k == 1:
            return min(a[0], b[0])

        mid_a = min(len(a), k // 2)
        mid_b = min(len(b), k // 2)

        if a[mid_a - 1] <= b[mid_b - 1]:
            return kth(a[mid_a:], b, k - mid_a)
        else:
            return kth(a, b[mid_b:], k - mid_b)

    return kth(arr1, arr2, k)
```

