def pair_xor_Sum(arr, n):
    total = 0
    for i in range(32):
        count_ones = 0
        for num in arr:
            if (num >> i) & 1:
                count_ones += 1
        count_zeros = n - count_ones
        total += (count_ones * count_zeros) * (1 << i)
    return total
```

