def wind_chill(wind_velocity, temperature):
    import math
    if wind_velocity < 4.8:
        return round(temperature)
    wind_speed_ms = wind_velocity / 3.6
    wind_chill = 13.12 + 0.6215 * temperature - 11.37 * (wind_speed_ms ** 0.16) + 0.3965 * temperature * (wind_speed_ms ** 0.16)
    return math.ceil(wind_chill)
```

