def set_left_most_unset_bit(n):
    # Find the position of the leftmost unset bit
    # Start from the most significant bit position
    bit_pos = n.bit_length() - 1
    while bit_pos >= 0:
        if not (n & (1 << bit_pos)):
            return n | (1 << bit_pos)
        bit_pos -= 1
    return n
```

```python
def set_left_most_unset_bit(n):
    if n & (n + 1) == 0:
        return n
    pos, temp, count = 0, n, 0
    while temp:
        if not (temp & 1):
            pos = count
        count += 1
        temp >>= 1
    return n | (1 << pos)
```

