```python
def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # inc[i] = maximum sum of increasing subsequence ending at i
    inc = [0] * n
    for i in range(n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i] and inc[j] + arr[i] > inc[i]:
                inc[i] = inc[j] + arr[i]

    # dec[i] = maximum sum of decreasing subsequence starting at i
    dec = [0] * n
    for i in range(n-1, -1, -1):
        dec[i] = arr[i]
        for j in range(i+1, n):
            if arr[j] < arr[i] and dec[j] + arr[i] > dec[i]:
                dec[i] = dec[j] + arr[i]

    # maximum bitonic sum = max(inc[i] + dec[i] - arr[i])
    max_sum_val = 0
    for i in range(n):
        max_sum_val = max(max_sum_val, inc[i] + dec[i] - arr[i])

    return max_sum_val
```

