def sum_of_digits(nums):
    total = 0
    stack = list(nums)
    while stack:
        item = stack.pop()
        if isinstance(item, (list, tuple)):
            stack.extend(item)
        else:
            for ch in str(item):
                if ch.isdigit():
                    total += int(ch)
    return total
