def amicable_numbers_sum(limit):
    if not isinstance(limit, int) or limit < 1:
        return "Input is not an integer or is less than 1!"

    def sum_divisors(n):
        total = 0
        for i in range(1, n // 2 + 1):
            if n % i == 0:
                total += i
        return total

    result = 0
    for num in range(2, limit + 1):
        partner = sum_divisors(num)
        if partner != num and sum_divisors(partner) == num:
            result += num
    return result
```

