def is_majority(arr, n, x):
    # Find the first occurrence of x using binary search
    left = 0
    right = n - 1
    first = -1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == x:
            first = mid
            right = mid - 1
        elif arr[mid] < x:
            left = mid + 1
        else:
            right = mid - 1

    if first == -1:
        return False

    # Check if x occurs more than n/2 times
    last = first + n // 2
    if last < n and arr[last] == x:
        return True
    return False
```

