def is_majority(arr, n, x):
    def first_occurrence(arr, low, high, x):
        res = -1
        while low <= high:
            mid = (low + high) // 2
            if arr[mid] == x:
                res = mid
                high = mid - 1
            elif arr[mid] < x:
                low = mid + 1
            else:
                high = mid - 1
        return res

    i = first_occurrence(arr, 0, len(arr) - 1, x)
    if i == -1:
        return False
    if i + n // 2 < len(arr) and arr[i + n // 2] == x:
        return True
    return False
