def max_sum_increasing_subseq(arr, n, i, k):
    dp = [0] * (i + 1)
    for j in range(i + 1):
        dp[j] = arr[j]
        for p in range(j):
            if arr[p] < arr[j]:
                dp[j] = max(dp[j], dp[p] + arr[j])
    result = 0
    for j in range(i + 1):
        if arr[j] < arr[k]:
            result = max(result, dp[j] + arr[k])
    return result
```

```python
def max_sum_increasing_subseq(a, n, index, k):
    dp = [0] * n
    for i in range(n):
        dp[i] = a[i]
        for j in range(i):
            if a[j] < a[i] and dp[j] + a[i] > dp[i]:
                dp[i] = dp[j] + a[i]
    best = 0
    for i in range(index + 1):
        if a[i] < a[k] and dp[i] + a[k] > best:
            best = dp[i] + a[k]
    return best
```

