def max_Product(arr):
    if len(arr) < 2:
        return None

    # Find the two largest numbers and two smallest numbers
    max1 = max2 = float('-inf')
    min1 = min2 = float('inf')

    for num in arr:
        # Update largest
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

        # Update smallest
        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    # Compare products
    if max1 * max2 > min1 * min2:
        return (max2, max1)
    else:
        return (min1, min2)
```

