def magic_square_test(matrix):
    n = len(matrix)
    if n == 0:
        return False
    target_sum = sum(matrix[0])
    for row in matrix:
        if len(row) != n or sum(row) != target_sum:
            return False
    for col in range(n):
        col_sum = sum(matrix[row][col] for row in range(n))
        if col_sum != target_sum:
            return False
    diag1 = sum(matrix[i][i] for i in range(n))
    diag2 = sum(matrix[i][n-1-i] for i in range(n))
    return diag1 == target_sum and diag2 == target_sum
```

