def magic_square_test(my_matrix):
    n = len(my_matrix)
    if n == 0:
        return False
    for row in my_matrix:
        if len(row) != n:
            return False

    target = sum(my_matrix[0])

    # rows
    for row in my_matrix:
        if sum(row) != target:
            return False

    # columns
    for col in range(n):
        if sum(my_matrix[row][col] for row in range(n)) != target:
            return False

    # diagonals
    if sum(my_matrix[i][i] for i in range(n)) != target:
        return False
    if sum(my_matrix[i][n - 1 - i] for i in range(n)) != target:
        return False

    return True
```

