def max_sub_array_sum_repeated(arr, n, k):
    def kadane(a):
        max_ending_here = max_so_far = a[0]
        for x in a[1:]:
            max_ending_here = max(x, max_ending_here + x)
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    total_sum = sum(arr)
    if k == 1:
        return kadane(arr)

    # For k > 1, the maximum subarray can be in:
    # 1. Single copy (kadane on arr)
    # 2. Across copies (kadane on arr*2) if total_sum > 0, else just kadane(arr)
    if total_sum <= 0:
        return kadane(arr)

    # If total_sum > 0, the best is kadane(arr*2) + (k-2)*total_sum
    double_arr = arr * 2
    max_in_two = kadane(double_arr)
    return max_in_two + (k - 2) * total_sum
```

```python
def max_sub_array_sum_repeated(a, n, k):
    def kadane(arr):
        best = arr[0]
        cur = arr[0]
        for x in arr[1:]:
            cur = max(x, cur + x)
            best = max(best, cur)
        return best

    total = sum(a)
    if k == 1:
        return kadane(a)

    two = kadane(a * 2)
    if total > 0:
        return two + (k - 2) * total
    return two
```

